def gradient_descent(X, y, lr, n_iter):
    import numpy as np
    X, y = np.array(X), np.array(y)
    w = np.zeros(X.shape[1])
    for _ in range(n_iter):
        pred = X @ w
        grad = X.T @ (pred - y) / len(y)
        w -= lr * grad
    return w.tolist()

